<div class="intro-line"><p>Semua kamus rujukan memiliki halaman sendiri. Nilai resmi, nilai lokal, dan riwayat perubahannya dikelola dari sini.</p><span class="count-chip"><?= number_format($catalog_count,0,',','.') ?> master</span></div>
<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url('admin/master') ?>"><label class="search-field"><span>Cari master</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Nama atau kelompok master"></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small" type="submit">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url('admin/master') ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Kelompok</th><th>Master</th><th>Jenis sumber</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><span class="table-overline"><?= h($r['category']) ?></span></td><td><strong><?= h($r['title']) ?></strong><small class="cell-sub"><?= h($r['slug']) ?></small></td><td><span class="pill <?= $r['source_policy']==='official'?'pill-blue':'pill-muted' ?>"><?= $r['source_policy']==='official'?'Resmi':($r['source_policy']==='mixed'?'Campuran':'Lokal') ?></span></td><td><a class="row-link" href="<?= site_url('admin/master/'.$r['slug']) ?>">Kelola →</a></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="4" class="empty-cell">Tidak ada master yang sesuai pencarian.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
